import { test } from "node:test";
import * as assert from "node:assert/strict";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { execFileSync } from "node:child_process";
import { AgentWorkUnitExecutor, OperationStore } from "../src/core/operation_runner.js";
import { newOperation, type UnitRunContext, type UnitRunResult, type WorkUnit } from "../src/core/operation.js";
import { parseIndependentReviewVerdict } from "../src/core/independent_review.js";
import { TeamOrchestrator } from "../src/team.js";
import { fakeClock } from "./helpers/provider_fixture.js";
import type { HarnessConfig } from "../src/types.js";

function repo() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "zzrun-"));
  const g = (...a: string[]) => execFileSync("git", a, { cwd: dir, stdio: "pipe", encoding: "utf8" });
  g("init", "-q"); g("config", "user.email", "t@e"); g("config", "user.name", "t");
  fs.writeFileSync(path.join(dir, "math.js"), "export const add = (a, b) => a - b;\n"); g("add", "."); g("commit", "-qm", "base");
  return { dir, g };
}
const verdict = JSON.stringify({ verdict: "ACCEPT", verifiedObservations: ["ok"], suspectedDefects: [], unprovenCriteria: [], scopeViolations: [], reviewerConfidenceNote: "ok" });
const resources = [{ id: "r1", provider: "https://p1.test", endpoint: "https://p1.test/v1", model: "r1", capabilities: ["tools"], rank: 0 }];

test("B migration: older operation (implementer already committed, no startCommit) resumed", async () => {
  const { dir, g } = repo();
  const base = g("rev-parse", "HEAD").trim();
  fs.writeFileSync(path.join(dir, "math.js"), "export const add = (a, b) => a + b;\n"); g("commit", "-qam", "fix");
  const store = new OperationStore(dir, fs.mkdtempSync(path.join(os.tmpdir(), "zzst-")));
  const clock = fakeClock();
  const state: any = newOperation("op-old", "Fix add", [{ id: "implement", role: "implementer", prompt: "fix" }, { id: "review", role: "reviewer", prompt: "review", dependsOn: ["implement"] }], resources as any, clock.now());
  const impl = state.units.find((u: any) => u.id === "implement");
  impl.status = "COMPLETE"; impl.runs = 1; impl.result = { summary: "done", completedAt: new Date().toISOString(), resourceId: "r1", outcome: "NOT_REQUIRED" };
  const seen: UnitRunContext[] = [];
  const executor = { async run(u: WorkUnit, _r: unknown, ctx: UnitRunContext): Promise<UnitRunResult> { seen.push(ctx); return { kind: "completed", summary: "ACCEPT: ok", outcome: "NOT_REQUIRED" }; } };
  const config = { endpoint: "https://p1.test/v1", model: "m", maxSteps: 4, temperature: 0, workspace: dir, shell: "bash" } as HarnessConfig;
  await new TeamOrchestrator(config, { store, executor, clock, resources } as any).drive(state);
  const ctx = seen.find((c) => c) as any;
  console.log("PROBE B startCommit==base?", ctx?.startCommit === base, "startCommit==HEAD?", ctx?.startCommit === g("rev-parse", "HEAD").trim());
  const real = new AgentWorkUnitExecutor({ baseConfig: config });
  const pkg = (real as any).reviewEvidence({ id: "review", title: "R", role: "reviewer", prompt: "r" }, { ...ctx, workspace: dir }, dir);
  console.log("PROBE B diff length", pkg.unifiedDiff.length, "diffError", pkg.diffError, "exit", pkg.verifierExitCode);
  const out = parseIndependentReviewVerdict(verdict, pkg);
  console.log("PROBE B verdict on empty-diff migrated review:", out.verdict, JSON.stringify(out.unprovenCriteria));
});

test("C1 failed-verifier receipt + ACCEPT; C2 two deps, first PASSED second FAILED", () => {
  const { dir, g } = repo();
  fs.writeFileSync(path.join(dir, "math.js"), "export const add = (a, b) => a + b;\n");
  const real = new AgentWorkUnitExecutor({ baseConfig: {} as HarnessConfig });
  const start = g("rev-parse", "HEAD").trim();
  const mk = (deps: any[]) => (real as any).reviewEvidence({ id: "review", title: "R", role: "reviewer", prompt: "r" }, { objective: "o", workspace: dir, startCommit: start, operationId: "op", dependencies: deps }, dir);
  const F = { command: "make test", status: "FAILED", hasExecutedTests: true }, P = { command: "make test", status: "PASSED", hasExecutedTests: true };
  console.log("PROBE C1", parseIndependentReviewVerdict(verdict, mk([{ id: "i", title: "i", summary: "s", verification: F }])).verdict);
  console.log("PROBE C2 [PASSED,FAILED]", parseIndependentReviewVerdict(verdict, mk([{ id: "i", title: "i", summary: "s", verification: P }, { id: "t", title: "t", summary: "s", verification: F }])).verdict);
  console.log("PROBE C2b [FAILED,PASSED]", parseIndependentReviewVerdict(verdict, mk([{ id: "i", title: "i", summary: "s", verification: F }, { id: "t", title: "t", summary: "s", verification: P }])).verdict);
  // no evidence + big diff
  fs.writeFileSync(path.join(dir, "big.txt"), Array.from({ length: 4000 }, (_, i) => `line ${i}`).join("\n") + "\n");
  const big = mk([{ id: "i", title: "i", summary: "s" }]);
  console.log("PROBE C3 big no-evidence len", big.unifiedDiff.length, parseIndependentReviewVerdict(verdict, big).verdict);
  // small diff no evidence -> ?
  const { dir: d2, g: g2 } = repo(); fs.writeFileSync(path.join(d2, "math.js"), "export const add = (a, b) => a + b;\n");
  const small = (real as any).reviewEvidence({ id: "review", title: "R", role: "reviewer", prompt: "r" }, { objective: "o", workspace: d2, startCommit: g2("rev-parse", "HEAD").trim(), dependencies: [{ id: "i", title: "i", summary: "s" }] }, d2);
  console.log("PROBE C4 small no-evidence", parseIndependentReviewVerdict(verdict, small).verdict);
  // empty diff, no evidence
  const { dir: d3, g: g3 } = repo();
  const empty = (real as any).reviewEvidence({ id: "review", title: "R", role: "reviewer", prompt: "r" }, { objective: "o", workspace: d3, startCommit: g3("rev-parse", "HEAD").trim(), dependencies: [{ id: "i", title: "i", summary: "s" }] }, d3);
  console.log("PROBE C5 EMPTY diff no-evidence", JSON.stringify(empty.unifiedDiff), parseIndependentReviewVerdict(verdict, empty).verdict);
});
EOF
